const pptxgen = require('pptxgenjs');

const W = 10;
const H = 5.625;

function addBg(slide, theme, opts = {}) {
  slide.background = { color: opts.color || theme.bg };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: opts.color || theme.bg }, line: { color: opts.color || theme.bg } });
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 0.12, h: H, fill: { color: theme.accent }, line: { color: theme.accent } });
  slide.addShape(pptx.ShapeType.rect, { x: 0.12, y: 0, w: 0.04, h: H, fill: { color: theme.secondary }, line: { color: theme.secondary } });
}

function addTitle(slide, title, theme, subtitle) {
  slide.addText(title, { x: 0.45, y: 0.24, w: 8.75, h: 0.42, fontFace: theme.fontHead, fontSize: 18, bold: true, color: theme.primary, margin: 0 });
  slide.addShape(pptx.ShapeType.line, { x: 0.45, y: 0.79, w: 8.9, h: 0, line: { color: theme.line, width: 1 } });
  if (subtitle) slide.addText(subtitle, { x: 0.45, y: 0.86, w: 8.8, h: 0.24, fontFace: theme.fontBody, fontSize: 8.5, color: theme.muted, margin: 0 });
}

function addFooter(slide, n, theme) {
  slide.addText(String(n).padStart(2, '0'), { x: 9.22, y: 5.05, w: 0.5, h: 0.22, fontFace: theme.fontBody, fontSize: 8, color: theme.muted, align: 'right', margin: 0 });
  slide.addShape(pptx.ShapeType.line, { x: 0.45, y: 5.18, w: 8.55, h: 0, line: { color: theme.line, width: 0.5 } });
}

function pill(slide, text, x, y, w, color, textColor = 'FFFFFF') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.28, rectRadius: 0.08, fill: { color }, line: { color } });
  slide.addText(text, { x: x + 0.06, y: y + 0.06, w: w - 0.12, h: 0.12, fontSize: 7.5, bold: true, color: textColor, align: 'center', margin: 0 });
}

function card(slide, x, y, w, h, theme, opts = {}) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: opts.fill || 'FFFFFF', transparency: opts.transparency || 0 }, line: { color: opts.line || theme.line, width: opts.width || 0.75 } });
}

function bullet(slide, text, x, y, w, theme, opts = {}) {
  slide.addShape(pptx.ShapeType.oval, { x, y: y + 0.055, w: 0.07, h: 0.07, fill: { color: opts.color || theme.accent }, line: { color: opts.color || theme.accent } });
  slide.addText(text, { x: x + 0.14, y, w, h: opts.h || 0.3, fontFace: theme.fontBody, fontSize: opts.size || 9.5, color: opts.textColor || theme.primary, fit: 'shrink', breakLine: false, margin: 0 });
}

function addStage(slide, label, text, x, y, w, theme, color) {
  card(slide, x, y, w, 0.92, theme, { fill: 'FFFFFF', line: color, width: 1.25 });
  slide.addText(label, { x: x + 0.12, y: y + 0.11, w: w - 0.24, h: 0.18, fontFace: theme.fontHead, fontSize: 11, bold: true, color, margin: 0 });
  slide.addText(text, { x: x + 0.12, y: y + 0.39, w: w - 0.24, h: 0.34, fontFace: theme.fontBody, fontSize: 7.5, color: theme.primary, fit: 'shrink', margin: 0.01 });
}

function arrow(slide, x1, y1, x2, y2, theme, color) {
  slide.addShape(pptx.ShapeType.line, { x: x1, y: y1, w: x2 - x1, h: y2 - y1, line: { color: color || theme.secondary, width: 1.4, beginArrowType: 'none', endArrowType: 'triangle' } });
}

function statusBadge(slide, text, x, y, accepted, theme) {
  const color = accepted ? theme.green : theme.red;
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w: 0.78, h: 0.19, rectRadius: 0.04, fill: { color }, line: { color } });
  slide.addText(text, { x, y: y + 0.035, w: 0.78, h: 0.08, fontSize: 5.8, bold: true, color: 'FFFFFF', align: 'center', margin: 0 });
}

function addTable(slide, rows, x, y, colWs, theme) {
  const rowH = 0.49;
  const headers = rows[0];
  let cx = x;
  headers.forEach((head, i) => {
    slide.addShape(pptx.ShapeType.rect, { x: cx, y, w: colWs[i], h: 0.34, fill: { color: theme.primary }, line: { color: theme.primary, width: 0.4 } });
    slide.addText(head, { x: cx + 0.04, y: y + 0.095, w: colWs[i] - 0.08, h: 0.08, fontSize: 6.5, bold: true, color: 'FFFFFF', margin: 0, fit: 'shrink' });
    cx += colWs[i];
  });
  for (let r = 1; r < rows.length; r++) {
    const yy = y + 0.34 + (r - 1) * rowH;
    cx = x;
    const fill = r % 2 === 1 ? 'FFFFFF' : theme.soft;
    rows[r].forEach((cell, i) => {
      slide.addShape(pptx.ShapeType.rect, { x: cx, y: yy, w: colWs[i], h: rowH, fill: { color: fill }, line: { color: theme.line, width: 0.35 } });
      const isOutcome = i === 2;
      slide.addText(cell, { x: cx + 0.05, y: yy + 0.07, w: colWs[i] - 0.1, h: rowH - 0.11, fontFace: theme.fontBody, fontSize: isOutcome ? 6.5 : 6.2, bold: isOutcome, color: isOutcome && cell.startsWith('Accept') ? theme.green : (isOutcome && cell.startsWith('Reject') ? theme.red : theme.primary), fit: 'shrink', valign: 'mid', margin: 0.01 });
      cx += colWs[i];
    });
  }
}

module.exports = { pptxgen, W, H, addBg, addTitle, addFooter, pill, card, bullet, addStage, arrow, statusBadge, addTable };
EOF

